CREATE TABLE pg_namespace (oid INTEGER NOT NULL PRIMARY KEY CHECK(oid BETWEEN 0 AND 4294967295), nspname TEXT COLLATE BINARY NOT NULL UNIQUE);
CREATE TABLE pg_class (oid INTEGER NOT NULL PRIMARY KEY CHECK(oid BETWEEN 0 AND 4294967295), relnamespace INTEGER NOT NULL REFERENCES pg_namespace(oid), relname TEXT COLLATE BINARY NOT NULL, relkind TEXT NOT NULL CHECK(length(relkind)=1), relnatts INTEGER NOT NULL CHECK(relnatts BETWEEN 0 AND 32767), UNIQUE(relnamespace,relname));
CREATE TABLE pg_attribute (attrelid INTEGER NOT NULL REFERENCES pg_class(oid), attnum INTEGER NOT NULL CHECK(attnum BETWEEN -32768 AND 32767 AND attnum != 0), attname TEXT COLLATE BINARY NOT NULL, attisdropped INTEGER NOT NULL CHECK(attisdropped IN (0,1)), PRIMARY KEY(attrelid,attnum));
CREATE TABLE snapshot_schema_access (nspoid INTEGER NOT NULL PRIMARY KEY REFERENCES pg_namespace(oid), usage_allowed INTEGER NOT NULL CHECK(usage_allowed IN (0,1)));
CREATE TABLE snapshot_search_path (position INTEGER NOT NULL PRIMARY KEY CHECK(position > 0), nspoid INTEGER NOT NULL UNIQUE REFERENCES pg_namespace(oid));
CREATE TABLE snapshot_meta (id INTEGER NOT NULL PRIMARY KEY CHECK(id=1), format_version INTEGER NOT NULL CHECK(format_version=1), server_version_num INTEGER NOT NULL, database_name TEXT NOT NULL, session_user TEXT NOT NULL, current_user TEXT NOT NULL, captured_at TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope='database_catalog'), complete INTEGER NOT NULL CHECK(complete=1), namespace_count INTEGER NOT NULL CHECK(namespace_count>=0), relation_count INTEGER NOT NULL CHECK(relation_count>=0), attribute_count INTEGER NOT NULL CHECK(attribute_count>=0), search_path_count INTEGER NOT NULL CHECK(search_path_count>=0));
